s=s.replace('uint64_t own=0;int own_count=0;\n            if(access){own=below[k];own_count=__builtin_popcountll(own);}', 'uint64_t own[4]{};int own_count=0;\n            if(access){for(int w=0;w<4;w++){own[w]=below[k][w];own_count+=__builtin_popcountll(own[w]);}}')
s=s.replace('int next_count=__builtin_popcountll(remaining[d+1]);quality+=next_count-own_count;own_count=next_count;\n                     if(xl>=kl)quality+=__builtin_popcountll((*access)[k]&~below[x]);', 'int next_count=0;for(int w=0;w<4;w++)next_count+=__builtin_popcountll(remaining[d+1][w]);quality+=next_count-own_count;own_count=next_count;\n                     if(xl>=kl)for(int w=0;w<4;w++)quality+=__builtin_popcountll((*access)[k][w]&~below[x][w]);')
s=s.replace('own|=(*access)[x];int next_count=__builtin_popcountll(own);quality+=next_count-own_count;own_count=next_count;', 'int next_count=0;for(int w=0;w<4;w++){own[w]|=(*access)[x][w];next_count+=__builtin_popcountll(own[w]);}quality+=next_count-own_count;own_count=next_count;')
